CREATE DATABASE MyExpenseTracker;GO USE MyExpenseTracker;GO CREATE TABLE AppUsers(Id INT IDENTITY PRIMARY KEY,UserName NVARCHAR(50) NOT NULL UNIQUE,PasswordHash NVARCHAR(500) NOT NULL);CREATE TABLE Accounts(Id INT IDENTITY PRIMARY KEY,Name NVARCHAR(100) NOT NULL,Type INT NOT NULL,OpeningBalance DECIMAL(18,2) NOT NULL);CREATE TABLE Transactions(Id INT IDENTITY PRIMARY KEY,AccountId INT NOT NULL REFERENCES Accounts(Id) ON DELETE CASCADE,Kind INT NOT NULL,TransactionDate DATETIME2 NOT NULL,Amount DECIMAL(18,2) NOT NULL,Category NVARCHAR(50) NOT NULL,Description NVARCHAR(1000) NOT NULL);CREATE TABLE Budgets(Id INT IDENTITY PRIMARY KEY,Year INT NOT NULL,Month INT NOT NULL,Category NVARCHAR(50) NOT NULL,Amount DECIMAL(18,2) NOT NULL,UNIQUE(Year,Month,Category));INSERT AppUsers(UserName,PasswordHash) VALUES('Alchemist','');GO -- Generate hash with PasswordHashTool, then: UPDATE AppUsers SET PasswordHash='HASH' WHERE UserName='Alchemist';